function hasDraft(d){return !!(d.text?.trim()||d.sharedContext?.trim()||Object.values(d.individualNotes||{}).some(x=>x.trim())||Object.values(d.individualChoices||{}).some(x=>x.length)||d.goalStep?.trim()||d.goalCriterion?.trim()||d.task?.trim()||d.situation?.trim()||d.title?.trim()||d.feedback?.trim()||d.choices?.length||d.status||d.support||d.supportNote?.trim()||d.due||d.needsFollowUp||d.goalId||d.orgTask||d.orgDue||d.orgDone||d.orgReminderEnabled||d.orgReminderDue||d.orgReminderText||participantValues(d).length);}
function saveDrafts(){if(storageMaintenanceBlocked()||readStorageRoot()!==storageRoot){setSaveStatus(false,'Entwurf nur in dieser Sitzung – Datenstand wird gepflegt');return;}for(const [key,d] of drafts){const [id,category]=[key.slice(0,key.lastIndexOf('|')),key.slice(key.lastIndexOf('|')+1)];const storageKey=DRAFT_PREFIX+documentId+':'+key;try{if(hasDraft(d)){const origin=restoredSources.get(key);if(origin&&localStorage.getItem(origin.key)===origin.raw&&JSON.stringify(JSON.parse(origin.raw).data)===JSON.stringify(d))continue;const previous=localStorage.getItem(storageKey);const next={studentId:id,category,data:copy(d),mode:category==='Hausübung'?homeMode:undefined,feedbackId:category==='Hausübung'?d.feedbackId:undefined};if(!previous||JSON.stringify(JSON.parse(previous).data)!==JSON.stringify(next.data))localStorage.setItem(storageKey,JSON.stringify({...next,updated:new Date().toISOString()}));}else localStorage.removeItem(storageKey);}catch{setSaveStatus(false,'Entwurf nur in dieser Sitzung – bitte exportieren');}}drawDraftBanner();}
