 const form=$('#entryForm');if(form){form.insertAdjacentHTML('beforeend',metadataFields(draft()));const support=$('#supportNeeded');if(support)support.onchange=()=>{draft().support=support.checked;saveDrafts();};if(section==='Hausübung'&&homeMode==='new'){form.insertAdjacentHTML('beforeend',`<div class="field"><label>Für welche Schüler?</label><div class="selection-targets">${db.students.filter(s=>!s.archived||s.id===active).map(s=>`<label><input type="checkbox" data-homework-target="${esc(s.id)}" ${(draft().targets||[active]).includes(s.id)?'checked':''}>${esc(s.name)}</label>`).join('')}</div>`);}if(section==='Hausübung'&&feedbackId){const statusGroup=form.querySelector('.status-options');statusGroup.insertAdjacentHTML('beforeend', ['notchecked','absent'].map(v=>`<button type="button" data-hwstatus="${v}" class="${draft().status===v?'selected':''}">${STATUS[v]}</button>`).join(''));statusGroup.insertAdjacentHTML('afterend',`<div class="field"><label for="delivery">Abgabe / Vorlage</label><select id="delivery" data-field="delivery">${Object.entries(DELIVERY).map(([v,label])=>`<option value="${v}" ${draft().delivery===v?'selected':''}>${label}</option>`).join('')}</select></div>`);}}
