function assignmentText(h){return 'Aufgegeben: '+h.title+(h.subject?'\nFach: '+h.subject:'')+(h.due?'\nFällig: '+shortDay(h.due):'');}
function feedbackText(h,status,delivery,text){return STATUS[status]+': '+h.title+'\nAbgabe: '+(DELIVERY[delivery]||DELIVERY.unknown)+(text?'\n'+text:'');}
