 if(e.category==='Ziele'){const due=$('#recordGoalDue').value;if(due&&!validTime(due)){db=prior;toast('Bitte einen gültigen Zieltermin eingeben.');return;}e.goalCriterion=$('#recordGoalCriterion')?.value.trim()||'';e.goalPerspective=$('#recordGoalPerspective')?.value.trim()||'';e.goalStep=$('#recordGoalStep').value.trim();e.goalDue=due;const nextStatus=$('#recordGoalStatus').value;if(nextStatus!==(e.goalStatus||'active'))applyGoalReview(e,{id:uid(),at:day(),outcome:nextStatus==='active'?'reopen':nextStatus,note:'Status geändert',nextStep:e.goalStep||'',nextDue:nextStatus==='active'?goalPresetDate('week'):''});}
