function deleteRecord(id){const e=db.entries.find(e=>e.id===id);if(!e)return;const affected=[{collection:'entries',id:e.id,before:e.deletedAt||null}];e.deletedAt=new Date().toISOString();if(e.linkedReminderId){const r=db.reminders.find(r=>r.id===e.linkedReminderId&&!r.deletedAt);if(r){affected.push({collection:'reminders',id:r.id,before:null});r.deletedAt=e.deletedAt;}for(const linked of db.entries.filter(x=>x.sourceEntryId===e.id&&!x.deletedAt)){affected.push({collection:'entries',id:linked.id,before:null});linked.deletedAt=e.deletedAt;}}if(e.reminderId){const r=db.reminders.find(r=>r.id===e.reminderId);if(r){affected.push({collection:'reminders',id:r.id,before:r.deletedAt||null});r.deletedAt=e.deletedAt;}}if(persist()){undoRecord=affected;renderStudents();if($('#studentDialog').open)renderModal();drawUndo();}else affected.forEach(x=>{db[x.collection].find(r=>r.id===x.id).deletedAt=x.before;});}
function drawUndo(){let e=$('#undoBanner');e.classList.toggle('hidden',!undoRecord);e.innerHTML=undoRecord?'Eintrag gelöscht. <button id="undoDelete">Rückgängig</button>':'';if(undoRecord){const open=[...document.querySelectorAll('dialog[open]')].at(-1);if(open)open.insertBefore(e,open.querySelector('.modal-body'));else $('.page-head').before(e);}}
