$('#commitPupil').onclick=()=>{const prior=copy(db);const s=db.students.find(s=>s.id===active),name=$('#pupilName').value.trim();if(!name){toast('Bitte einen Namen eingeben.');return;}if(name!==s.name)s.previousNames=[...new Set([...(s.previousNames||[]),s.name])];s.name=name;s.color=validPupilColor($('#pupilColor').value)?$('#pupilColor').value:pupilColor(s);s.archived=$('#pupilArchived').checked;if(persist()){$('#pupilDialog').close();$('#modalName').textContent=name;$('#modalAvatar').textContent=name.slice(0,1);renderStudents();renderModal();toast('Schülerdaten gespeichert.');}else{db=prior;toast('Änderung nicht gespeichert. Bitte erneut versuchen.');}};
// Import previews changes; no name-based matching and no silent conflict overwrite.
$('#importFile').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>15*1024*1024)throw Error('Datei zu groß (maximal 15 MB).');const value=await decodeBackupFile(await file.text());if(!valid(value))throw Error('Keine gültige FLEX-Sicherung.');pendingImport=value;configureImportReview();let added=0,conflicts=0;for(const key of COLLECTIONS)for(const item of value[key]||[]){const current=db[key].find(v=>v.id===item.id);if(!current)added++;else if(JSON.stringify(current)!==JSON.stringify(item))conflicts++;}const names=value.students.filter(s=>!db.students.some(v=>v.id===s.id)&&db.students.some(v=>v.name.toLocaleLowerCase('de')===s.name.toLocaleLowerCase('de')));$('#importSummary').innerHTML=`<p>${added} neue Datensätze · ${conflicts} bestehende Datensätze mit Abweichungen.</p>${names.length?'<p>Gleiche Namen mit unterschiedlichen IDs bleiben getrennt:</p><ul>'+names.map(s=>'<li>'+esc(s.name)+'</li>').join('')+'</ul>':''}<p>Hausübungsstände werden aus den übernommenen Rückmeldungen neu berechnet.</p>`;$('#importReview').showModal();}catch(error){toast(error.message||'Import fehlgeschlagen.');}finally{e.target.value='';}};
$('#confirmImport').onclick=commitImportRecords;
$('#exportData').onclick=exportBackup;
function downloadText(name,text,type='text/plain'){const url=URL.createObjectURL(new Blob([text],{type:type+';charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
// Conversation preparation remains a transparent selection of existing evidence.
function showBrief(){briefSelected.clear();$('#briefFrom').value='';$('#briefTo').value=day();$('#briefPreview').classList.add('hidden');$('#briefExport').classList.add('hidden');drawBriefItems();$('#briefDialog').showModal();}
function briefEntries(){return entriesFor().filter(e=>(!$('#briefFrom').value||e.at.slice(0,10)>=$('#briefFrom').value)&&(!$('#briefTo').value||e.at.slice(0,10)<=$('#briefTo').value));}
function drawBriefItems(){$('#briefItems').innerHTML=briefEntries().map(e=>`<label class="brief-selection"><input type="checkbox" data-brief-entry="${esc(e.id)}" ${briefSelected.has(e.id)?'checked':''}><span><small>${esc(fullDate(e.at))} · ${esc(e.category)}</small><p>${esc([participantText(e),e.category==='Ziele'?goalSummary(e):'',e.goalId?'Zielbezug: '+linkedGoalText(e):'',e.task?'Auftrag: '+e.task:'',e.situation?'Situation: '+e.situation:'',e.text,...e.choices.map(c=>c.text)].filter(Boolean).join('\n'))}</p></span></label>`).join('')||'<p class="help">Keine Einträge in diesem Zeitraum.</p>';}
$('#briefFrom').onchange=()=>{briefSelected.clear();drawBriefItems();};$('#briefTo').onchange=()=>{briefSelected.clear();drawBriefItems();};$('#selectBriefAll').onclick=()=>{briefEntries().forEach(e=>briefSelected.add(e.id));drawBriefItems();};$('#clearBrief').onclick=()=>{briefSelected.clear();drawBriefItems();};
$('#createBrief').onclick=()=>{const items=briefEntries().filter(e=>briefSelected.has(e.id));if(!items.length){toast('Bitte mindestens einen Eintrag auswählen.');return;}briefText='Gesprächsvorbereitung – '+pupilName(active)+'\nZeitraum: '+($('#briefFrom').value||'alle bisherigen Einträge')+' bis '+($('#briefTo').value||day())+'\n\n'+items.map(e=>fullDate(e.at)+' · '+e.category+'\n'+[participantText(e),e.category==='Ziele'?goalSummary(e):'',e.goalId?'Zielbezug: '+linkedGoalText(e):'',e.task?'Auftrag: '+e.task:'',e.situation?'Situation: '+e.situation:'',e.text,...e.choices.map(c=>(c.tone==='positive'?'+ ':'− ')+c.text),e.support?'Unterstützung: '+(e.supportNote||'benötigt'):''].filter(Boolean).join('\n')).join('\n\n')+'\n\nOffene Absprachen / Erinnerungen\n'+live(db.reminders).filter(r=>r.studentId===active&&!r.done).map(r=>'• '+r.text+' ('+fullDate(r.due)+')').join('\n')+'\n\nNächste Schritte\n';$('#briefPreview').textContent=briefText;$('#briefPreview').classList.remove('hidden');$('#briefExport').classList.remove('hidden');};
$('#copyBrief').onclick=async()=>{try{await navigator.clipboard.writeText(briefText);toast('Text kopiert.');}catch{toast('Kopieren nicht verfügbar. Bitte als Textdatei sichern.');}};$('#downloadBrief').onclick=()=>downloadText('FLEX-Gespraech-'+day()+'.txt',briefText);
// New controls are handled before the existing delegated handlers.
document.addEventListener('click',event=>{const b=event.target.closest('button');if(!b)return;const d=b.dataset;
 if(d.page){event.stopImmediatePropagation();switchPage(d.page);return;}
 if(b.id==='saveNext'){event.preventDefault();save(true);return;}
 if(d.editRecord){editRecord(d.editRecord);return;}if(d.deleteRecord){deleteRecord(d.deleteRecord);return;}if(d.reviewRecord){const e=db.entries.find(e=>e.id===d.reviewRecord);const prior=copy(db);if(pendingFollowUp(e)){e.reviewed=true;}else{e.needsFollowUp=true;e.reviewed=false;}if(persist()){renderStudents();if($('#studentDialog').open)renderModal();}else{db=prior;toast('Noch nicht gespeichert. Bitte erneut versuchen.');}return;}
 if(b.id==='undoDelete'){undoDelete();return;}
 if(d.removeRecordChoice!==undefined){b.closest('.record-choice').remove();return;}if(b.id==='addRecordChoice'){$('#recordChoices').insertAdjacentHTML('beforeend',recordChoice());return;}
 if(b.id==='managePupil'){managePupil();return;}if(b.id==='prepareBrief'){showBrief();return;}
 if(b.id==='showDrafts'||b.id==='pupilDrafts'){showDrafts();return;}if(d.resumeDraft){restoreOneDraft(d.resumeDraft);return;}
 if(d.discardDraft){requestDraftDiscard(d.discardDraft);return;}
 if(d.favorite){const prior=copy(db);db.favorites||={};db.favorites[section]||={};const list=db.favorites[section][tone]||[];db.favorites[section][tone]=list.includes(d.favorite)?list.filter(v=>v!==d.favorite):[...list,d.favorite];if(!persist()){db=prior;toast('Favorit nicht gespeichert.');}renderModal();return;}
 if(b.id==='toggleAllChoices'){showAllChoices=!showAllChoices;renderModal();return;}
 if(d.category){showAllChoices=false;}
 if(d.openHw){const h=db.homework.find(h=>h.id===d.openHw);openStudent(h.studentId);section='Hausübung';homeMode='feedback';feedbackId=h.id;draft().feedbackId=h.id;renderModal();return;}
 if(d.openReminder){const r=db.reminders.find(r=>r.id===d.openReminder);if(r?.sourceEntryId){editRecord(r.sourceEntryId);return;}if(r){openStudent(r.studentId);section='Organisatorisches';renderModal();}return;}
 if(d.openEntry){const e=db.entries.find(e=>e.id===d.openEntry);openStudent(e.studentId);section='Verlauf';historyFilter.q=e.text.slice(0,30);renderModal();return;}
},true);
document.addEventListener('change',e=>{if(e.target.dataset.homeworkTarget){const d=draft(),id=e.target.dataset.homeworkTarget;d.targets=e.target.checked?[...new Set([...d.targets,id])]:d.targets.filter(v=>v!==id);saveDrafts();}if(e.target.dataset.briefEntry){if(e.target.checked)briefSelected.add(e.target.dataset.briefEntry);else briefSelected.delete(e.target.dataset.briefEntry);}});
window.addEventListener('storage',e=>{if(e.key?.startsWith(OP_PREFIX)){try{db=materialize();baseline=copy(db);try{localStorage.setItem(KEY,JSON.stringify(db));}catch{}renderStudents();setSaveStatus(true,'Änderungen aus anderem Tab übernommen');if($('#studentDialog').open&&(!section||section==='Verlauf'))renderModal();}catch{warn('Änderungen eines anderen Tabs konnten nicht geladen werden. Bitte exportieren.');}}if(e.key?.startsWith(DRAFT_PREFIX))drawDraftBanner();});
setSaveStatus(canStore);drawDraftBanner();
$('#confirmImport').onclick=commitImportRecords;
$('#studentDialog').addEventListener('close',()=>{const banner=$('#undoBanner');if(banner&&banner.closest('dialog'))$('.page-head').before(banner);renderStudents();});
const commitOptionsBase=commitOptions;
commitOptions=function(){const prior=copy(db),priorDrafts=[...drafts].map(([key,d])=>[key,copy(d)]);commitOptionsBase();if(!$('#optionsDialog').open&&!saveHealthy){db=prior;drafts.clear();priorDrafts.forEach(([key,d])=>drafts.set(key,d));$('#optionsDialog').showModal();editorError('Die Änderungen sind noch nicht gespeichert. Bitte erneut versuchen oder die Daten exportieren.');}};
$('#saveOptions').onclick=commitOptions;
